mapper.select:
WITH eligible AS ( SELECT r.id, r.order_id, r.customer_id FROM finance_receivable r JOIN sales_order so ON so.id = r.order_id AND so.deleted = FALSE JOIN customer c ON c.id = r.customer_id AND c.deleted = FALSE WHERE r.deleted = FALSE AND r.entry_type = 'NORMAL' AND r.settlement_customer_id = #{query.settlementCustomerId} AND r.customer_id = #{query.customerId}
AND EXISTS (SELECT 1 FROM finance_receivable_item ri WHERE ri.receivable_id = r.id AND ri.deleted = FALSE) AND NOT EXISTS ( SELECT 1 FROM finance_receivable_item ri LEFT JOIN inventory_outbound_item oi ON ri.source_type = 'INVENTORY_OUTBOUND_ITEM' AND oi.id = ri.source_id AND oi.deleted = FALSE LEFT JOIN inventory_outbound ib ON ib.id = oi.outbound_id AND ib.deleted = FALSE WHERE ri.receivable_id = r.id AND ri.deleted = FALSE AND ( ib.warehouse_id IS NULL
OR ib.warehouse_id NOT IN #{id}
OR TRUE
) )
), scoped_receipts AS ( SELECT rc.* FROM finance_receipt rc JOIN customer c ON c.id = rc.customer_id AND c.deleted = FALSE WHERE rc.deleted = FALSE AND rc.settlement_customer_id = #{query.settlementCustomerId} AND rc.customer_id = #{query.customerId}
), events AS ( SELECT 'RECEIVABLE'::varchar AS fact_type, r.id AS fact_id, r.event_at, r.receivable_no AS document_no, so.order_no AS related_no, r.customer_id, r.customer_name_snapshot AS customer_name, r.amount AS receivable_delta, 0::numeric AS receipt_delta, 0::numeric AS write_off_delta, 0::numeric AS refund_delta, r.created_at FROM finance_receivable r JOIN eligible e ON e.id = r.id JOIN sales_order so ON so.id = r.order_id AND so.deleted = FALSE UNION ALL SELECT 'RED', r.id, r.event_at, r.receivable_no, so.order_no, r.customer_id, r.customer_name_snapshot, -r.amount, 0, 0, 0, r.created_at FROM finance_receivable r JOIN eligible e ON e.id = r.original_receivable_id JOIN sales_order so ON so.id = r.order_id AND so.deleted = FALSE WHERE r.deleted = FALSE AND r.entry_type = 'RED' AND r.settlement_customer_id = #{query.settlementCustomerId} UNION ALL SELECT CASE WHEN rc.entry_type = 'NORMAL' THEN 'RECEIPT' ELSE 'RECEIPT_REVERSE' END, rc.id, rc.received_at, rc.receipt_no, original.receipt_no, rc.customer_id, rc.customer_name_snapshot, 0, CASE WHEN rc.entry_type = 'NORMAL' THEN rc.amount ELSE -rc.amount END, 0, 0, rc.created_at FROM scoped_receipts rc LEFT JOIN finance_receipt original ON original.id = rc.reverse_of_id UNION ALL SELECT CASE WHEN wo.entry_type = 'NORMAL' THEN 'WRITE_OFF' ELSE 'WRITE_OFF_REVERSE' END, wo.id, wo.written_off_at, wo.write_off_no, ar.receivable_no, ar.customer_id, ar.customer_name_snapshot, CASE WHEN wo.entry_type = 'NORMAL' THEN -wo.amount ELSE wo.amount END, 0, CASE WHEN wo.entry_type = 'NORMAL' THEN wo.amount ELSE -wo.amount END, 0, wo.created_at FROM finance_write_off wo JOIN finance_receivable ar ON ar.id = wo.target_id AND ar.deleted = FALSE JOIN eligible e ON e.id = CASE WHEN ar.entry_type = 'NORMAL' THEN ar.id ELSE ar.original_receivable_id END JOIN scoped_receipts rc ON wo.source_type = 'RECEIPT' AND rc.id = wo.source_id WHERE wo.deleted = FALSE AND wo.target_type = 'RECEIVABLE' UNION ALL SELECT CASE WHEN p.entry_type = 'NORMAL' THEN 'REFUND' ELSE 'REFUND_REVERSE' END, p.id, p.paid_at, p.payment_no, refund.refund_no, p.counterparty_id, p.counterparty_name_snapshot, 0, 0, 0, CASE WHEN p.entry_type = 'NORMAL' THEN p.amount ELSE -p.amount END, p.created_at FROM finance_payment p JOIN finance_payment original ON original.id = COALESCE(p.reverse_of_id, p.id) AND original.counterparty_type = 'CUSTOMER' AND original.source_type = 'ORDER_REFUND' JOIN order_refund refund ON refund.id = original.source_id JOIN sales_order so ON so.id = refund.order_id AND so.deleted = FALSE AND so.customer_id = p.counterparty_id AND so.settlement_customer_id = #{query.settlementCustomerId} JOIN customer c ON c.id = p.counterparty_id AND c.deleted = FALSE WHERE p.deleted = FALSE AND p.counterparty_type = 'CUSTOMER' AND p.counterparty_id = #{query.customerId}
AND EXISTS (SELECT 1 FROM inventory_outbound_item oi WHERE oi.sales_order_id = so.id AND oi.deleted = FALSE) AND NOT EXISTS ( SELECT 1 FROM inventory_outbound_item oi LEFT JOIN inventory_outbound ib ON ib.id = oi.outbound_id AND ib.deleted = FALSE WHERE oi.sales_order_id = so.id AND oi.deleted = FALSE AND ( ib.warehouse_id IS NULL
OR ib.warehouse_id NOT IN #{id}
OR TRUE
) )
) SELECT fact_type AS factType, fact_id AS factId, event_at AS eventAt, document_no AS documentNo, related_no AS relatedNo, customer_id AS customerId, customer_name AS customerName, receivable_delta AS receivableDelta, receipt_delta AS receiptDelta, write_off_delta AS writeOffDelta, refund_delta AS refundDelta FROM events WHERE event_at < #{endAt} AND created_at <= #{asOfCreatedAt} ORDER BY event_at, fact_type, fact_id LIMIT #{limit}

SELECT * FROM scm_customer_statement
WHERE settlement_customer_id = #{settlementCustomerId} AND generated_by_employee_id = #{employeeId}
ORDER BY generated_at DESC, id DESC LIMIT 50
